//! TS-SDK parity tests — AtomicBEEF parsing, BRC-29 key derivation, and
//! BIP-143 sighash preimage byte-equality against `@bsv/sdk 1.10.1` fixtures.
//!
//! Fixtures are generated by `tests/parity/ts-fixtures/generate.mjs` and
//! stored under `tests/parity/fixtures/parity/*.json`. Each asserts a
//! specific byte-level invariant:
//!
//! - `atomic_beef_*.json` — our [`bsv_rs::transaction::Beef::from_binary`]
//!   must parse the TS-produced AtomicBEEF and recover the embedded new-tx
//!   id (which is byte-reversed in the header — 0x01010101 magic + 32-byte
//!   txid + BEEF_V2 body).
//! - `brc29_payment_*.json` — given (sender, prefix, suffix, receiver), our
//!   [`super::brc42::derive_brc29_input_key`] (computed sender-side) must
//!   produce the same child pubkey the TS sender derived. Verifies
//!   incoming-payment handling.
//! - `sighash_*.json` — given a synthetic tx + subscript + satoshis, our
//!   [`bsv_rs::primitives::bsv::sighash::compute_sighash_for_signing`] must
//!   yield the same preimage AND the same sighash digest as
//!   `TransactionSignature.format(...)` in TS.

#![allow(clippy::unwrap_used)]
#![allow(clippy::expect_used)]
#![allow(clippy::panic)]

use bsv_rs::primitives::bsv::sighash::{
    build_sighash_preimage, compute_sighash_for_signing, SighashParams, TxInput, TxOutput,
};
use bsv_rs::primitives::ec::{PrivateKey, PublicKey};
use bsv_rs::primitives::encoding::{from_hex, to_hex};
use bsv_rs::primitives::hash::sha256d;
use bsv_rs::transaction::Beef;
use bsv_rs::wallet::{Counterparty, KeyDeriver, Protocol, SecurityLevel};
use serde::Deserialize;

// ============================================================================
// 1. AtomicBEEF fixture round-trip
// ============================================================================

#[derive(Deserialize)]
struct AtomicBeefFixture {
    /// Optional single-parent fixtures carry this.
    #[serde(default)]
    parent_txid: Option<String>,
    /// Multi-parent fixtures carry this.
    #[serde(default)]
    parent_txids: Option<Vec<String>>,
    child_txid: String,
    beef_bytes: Vec<u8>,
}

const ATOMIC_BEEF_FIXTURES: &[(&str, &str)] = &[
    (
        "atomic_beef_1input_p2pkh",
        include_str!("../../tests/parity/fixtures/parity/atomic_beef_1input_p2pkh.json"),
    ),
    (
        "atomic_beef_2input_p2pkh",
        include_str!("../../tests/parity/fixtures/parity/atomic_beef_2input_p2pkh.json"),
    ),
    (
        "atomic_beef_1input_brc29_source",
        include_str!("../../tests/parity/fixtures/parity/atomic_beef_1input_brc29_source.json"),
    ),
];

/// The AtomicBEEF wire format is `0x01010101 || <reversed txid> || BEEF_V2 body`.
/// Strip the 36-byte atomic header and feed the rest to `Beef::from_binary`,
/// then verify the embedded new-tx txid matches `child_txid`.
#[test]
fn atomic_beef_fixtures_parse_and_match_child_txid() {
    for (name, raw) in ATOMIC_BEEF_FIXTURES {
        let f: AtomicBeefFixture = serde_json::from_str(raw).unwrap();
        let bytes = &f.beef_bytes;
        assert!(bytes.len() > 36, "{name}: atomic beef too short");

        // Header: magic 4 bytes + 32-byte txid (byte-reversed from display hex).
        let magic = u32::from_le_bytes(bytes[0..4].try_into().unwrap());
        assert_eq!(magic, 0x0101_0101, "{name}: wrong AtomicBEEF magic");
        let mut embedded_txid_bytes = [0u8; 32];
        embedded_txid_bytes.copy_from_slice(&bytes[4..36]);
        embedded_txid_bytes.reverse(); // internal → display
        let embedded_txid_hex = to_hex(&embedded_txid_bytes);
        assert_eq!(
            embedded_txid_hex, f.child_txid,
            "{name}: AtomicBEEF header txid does not match child_txid"
        );

        // Body: standard BEEF starting at byte 36.
        let body = &bytes[36..];
        let beef = Beef::from_binary(body)
            .unwrap_or_else(|e| panic!("{name}: Beef::from_binary failed: {e:?}"));

        // The child must be present in the beef.
        let found = beef.find_txid(&f.child_txid);
        assert!(
            found.is_some(),
            "{name}: child_txid {} not found in parsed BEEF",
            f.child_txid
        );

        // Parent(s) must be present too — AtomicBEEF carries ancestors.
        let parents: Vec<String> = match (&f.parent_txid, &f.parent_txids) {
            (Some(t), _) => vec![t.clone()],
            (None, Some(ts)) => ts.clone(),
            _ => vec![],
        };
        for p in parents {
            assert!(
                beef.find_txid(&p).is_some(),
                "{name}: parent tx {p} not found in BEEF"
            );
        }
    }
}

// ============================================================================
// 2. BRC-29 payment-output key derivation parity
// ============================================================================

#[derive(Deserialize)]
struct Brc29PaymentInput {
    #[allow(dead_code)]
    protocol: (u8, String),
    #[allow(dead_code)]
    key_id: String,
    derivation_prefix: String,
    derivation_suffix: String,
    counterparty: String,
    for_self: bool,
}

#[derive(Deserialize)]
struct Brc29PaymentExpected {
    derived_pubkey_hex: String,
    locking_script_hex: String,
    #[allow(dead_code)]
    tx_hex: String,
    #[allow(dead_code)]
    satoshis: u64,
}

#[derive(Deserialize)]
struct Brc29PaymentFixture {
    sender_priv_hex: String,
    #[allow(dead_code)]
    sender_pub_hex: String,
    #[allow(dead_code)]
    receiver_priv_hex: String,
    receiver_pub_hex: String,
    derivation: Brc29PaymentInput,
    expected: Brc29PaymentExpected,
}

const BRC29_FIXTURES: &[(&str, &str)] = &[
    (
        "brc29_payment_basic",
        include_str!("../../tests/parity/fixtures/parity/brc29_payment_basic.json"),
    ),
    (
        "brc29_payment_large_keyid",
        include_str!("../../tests/parity/fixtures/parity/brc29_payment_large_keyid.json"),
    ),
];

/// Sender derives the RECEIVER's child pubkey (for_self=false,
/// counterparty=receiver_pubkey_hex) under protocol `(2, "3241645161d8")`.
/// This is the mirror of what `derive_brc29_input_key` does on the
/// receiver side; here we verify our `KeyDeriver` computes the same child
/// when driven sender-side.
#[test]
fn brc29_payment_sender_derivation_matches_ts() {
    for (name, raw) in BRC29_FIXTURES {
        let f: Brc29PaymentFixture = serde_json::from_str(raw).unwrap();

        // Sender-side derive_public_key: identity = sender, counterparty =
        // receiver, for_self = false (we want receiver's child).
        let sender = PrivateKey::from_hex(&f.sender_priv_hex).unwrap();
        let receiver_pub = PublicKey::from_hex(&f.receiver_pub_hex).unwrap();
        let deriver = KeyDeriver::new(Some(sender));
        let protocol = Protocol::new(SecurityLevel::Counterparty, "3241645161d8");
        let key_id = format!(
            "{} {}",
            f.derivation.derivation_prefix, f.derivation.derivation_suffix
        );

        let derived = deriver
            .derive_public_key(
                &protocol,
                &key_id,
                &Counterparty::Other(receiver_pub),
                f.derivation.for_self,
            )
            .unwrap();
        assert_eq!(
            derived.to_hex(),
            f.expected.derived_pubkey_hex,
            "{name}: derived pubkey does not match TS"
        );

        // Sanity-check: counterparty echoed in fixture matches receiver.
        assert_eq!(
            f.derivation.counterparty, f.receiver_pub_hex,
            "{name}: fixture counterparty != receiver_pub_hex"
        );

        // And the derived pubkey's hash160 must match the P2PKH locking
        // script wallet-infra would have emitted for this payment output.
        let expected_lock = from_hex(&f.expected.locking_script_hex).unwrap();
        assert_eq!(expected_lock.len(), 25, "{name}: expected 25-byte P2PKH");
        assert_eq!(&expected_lock[0..3], &[0x76, 0xa9, 0x14]);
        assert_eq!(&expected_lock[23..], &[0x88, 0xac]);
        let expected_hash = &expected_lock[3..23];
        let actual_hash = derived.hash160();
        assert_eq!(
            expected_hash,
            &actual_hash[..],
            "{name}: derived pubkey hash160 doesn't match locking script hash"
        );
    }
}

// ============================================================================
// 3. BIP-143 sighash preimage parity
// ============================================================================

#[derive(Deserialize)]
struct SighashInputRow {
    source_txid: String,
    source_vout: u32,
    source_satoshis: u64,
    source_locking_script_hex: String,
    sequence: u32,
}

#[derive(Deserialize)]
struct SighashOutputRow {
    satoshis: u64,
    locking_script_hex: String,
}

#[derive(Deserialize)]
struct SighashInput {
    #[allow(dead_code)]
    tx_hex: String,
    inputs: Vec<SighashInputRow>,
    outputs: Vec<SighashOutputRow>,
    input_index: usize,
    version: i32,
    locktime: u32,
    scope: u32,
}

#[derive(Deserialize)]
struct SighashExpected {
    preimage_hex: String,
    sighash_digest_hex: String,
}

#[derive(Deserialize)]
struct SighashFixture {
    input: SighashInput,
    expected: SighashExpected,
}

const SIGHASH_FIXTURES: &[(&str, &str)] = &[
    (
        "sighash_p2pkh_1input",
        include_str!("../../tests/parity/fixtures/parity/sighash_p2pkh_1input.json"),
    ),
    (
        "sighash_p2pkh_2inputs_sign_first",
        include_str!("../../tests/parity/fixtures/parity/sighash_p2pkh_2inputs_sign_first.json"),
    ),
    (
        "sighash_p2pkh_2inputs_sign_second",
        include_str!("../../tests/parity/fixtures/parity/sighash_p2pkh_2inputs_sign_second.json"),
    ),
    (
        "sighash_pushdrop_subscript",
        include_str!("../../tests/parity/fixtures/parity/sighash_pushdrop_subscript.json"),
    ),
];

/// Convert a display-order txid hex to internal (little-endian) byte array.
fn internal_txid(display_hex: &str) -> [u8; 32] {
    let mut bytes = from_hex(display_hex).unwrap();
    assert_eq!(bytes.len(), 32);
    bytes.reverse();
    let mut out = [0u8; 32];
    out.copy_from_slice(&bytes);
    out
}

#[test]
fn sighash_preimage_and_digest_match_ts_fixtures() {
    for (name, raw) in SIGHASH_FIXTURES {
        let f: SighashFixture = serde_json::from_str(raw).unwrap();

        let tx_inputs: Vec<TxInput> = f
            .input
            .inputs
            .iter()
            .map(|r| TxInput {
                txid: internal_txid(&r.source_txid),
                output_index: r.source_vout,
                script: Vec::new(),
                sequence: r.sequence,
            })
            .collect();
        let tx_outputs: Vec<TxOutput> = f
            .input
            .outputs
            .iter()
            .map(|r| TxOutput {
                satoshis: r.satoshis,
                script: from_hex(&r.locking_script_hex).unwrap(),
            })
            .collect();

        let signing = &f.input.inputs[f.input.input_index];
        let subscript = from_hex(&signing.source_locking_script_hex).unwrap();

        let params = SighashParams {
            version: f.input.version,
            inputs: &tx_inputs,
            outputs: &tx_outputs,
            locktime: f.input.locktime,
            input_index: f.input.input_index,
            subscript: &subscript,
            satoshis: signing.source_satoshis,
            scope: f.input.scope,
        };

        let preimage = build_sighash_preimage(&params);
        assert_eq!(
            to_hex(&preimage),
            f.expected.preimage_hex,
            "{name}: preimage bytes differ"
        );

        let digest = compute_sighash_for_signing(&params);
        let digest_via_hash = sha256d(&preimage);
        assert_eq!(
            digest, digest_via_hash,
            "{name}: compute_sighash_for_signing disagrees with raw sha256d"
        );
        assert_eq!(
            to_hex(&digest),
            f.expected.sighash_digest_hex,
            "{name}: sighash digest differs from TS"
        );
    }
}
